css:
/* Quotation — grey original visual, new structural layout */

@font-face {
    font-family: "TH Sarabun Document";
    src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
    font-style: normal;
    font-weight: 400 700;
    font-display: block;
}

@page {
    size: 210mm 297mm;
    margin: 0;
}

html,
body {
    margin: 0 !important;
    padding: 0 !important;
}

.print-format {
    width: 210mm !important;
    min-height: 297mm !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
}

.cd-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.cd-table tr {
    break-inside: avoid;
    page-break-inside: avoid;
}

.cdq.cdq {
    --cd-font: "TH Sarabun Document", "TH SarabunPSK", "Noto Sans Thai", sans-serif;

    --cd-ink: #202020;
    --cd-muted: #5f6368;
    --cd-border: #202020;
    --cd-accent: #b3b3b3;
    --copy-color: var(--cd-accent);

    --cd-rule-w: .215mm;
    --cd-rule: var(--cd-rule-w) solid var(--cd-border);
    --cd-radius: 3.20mm;
    --cd-pill-radius: 6mm;

    --cd-page-x: 13.81mm;
    --cd-page-w: 189.90mm;

    --cd-top-top: 53.20mm;
    --cd-top-h: 49.80mm;
    --cd-top-gap: 1.50mm;

    --cd-intro-top: 104.50mm;
    --cd-intro-h: 7mm;

    --cd-grid-top: 112.50mm;
    --cd-head-h: 8.64mm;
    --cd-body-h: 91.50mm;
    --cd-summary-h: 39mm;
    --cd-grid-h: calc(
        var(--cd-head-h) +
        var(--cd-body-h) +
        var(--cd-summary-h)
    );

    --cd-footer-top: calc(var(--cd-grid-top) + var(--cd-grid-h));
    --cd-footer-h: 36.10mm;

    --cd-row-line-h: 4.25mm;
    --cd-row-pad-top: 2mm;
    --cd-row-pad-bottom: .65mm;
    --cd-row-min-h: 8.50mm;

    --cd-col-no: 11mm;
    --cd-col-desc: 89.90mm;
    --cd-col-qty: 30mm;
    --cd-col-rate: 29.50mm;
    --cd-col-amount: 29.50mm;

    --cd-x-desc: var(--cd-col-no);
    --cd-x-qty: calc(var(--cd-col-no) + var(--cd-col-desc));
    --cd-x-rate: calc(var(--cd-x-qty) + var(--cd-col-qty));
    --cd-x-amount: calc(var(--cd-x-rate) + var(--cd-col-rate));

    box-sizing: border-box;
    position: relative;
    width: 210mm;
    height: 297mm;
    margin: 0;
    overflow: hidden;
    color: var(--cd-ink);
    background: #fff;
    font-family: var(--cd-font) !important;
    font-size: 4.10mm !important;
    font-weight: 400;
    line-height: 1;
    break-after: page;
    page-break-after: always;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.cdq.cdq * {
    box-sizing: border-box;
    font-family: inherit !important;
}

.cdq.last-page {
    break-after: auto;
    page-break-after: auto;
}


/* Header */

.cdq .cd-corporate-header {
    position: absolute;
    left: 0;
    top: 0;
    width: 210mm;
    height: 52.30mm;
}

.cdq .cd-corporate-header > * {
    position: absolute;
    margin: 0;
    white-space: nowrap;
}

.cdq .company-logo {
    left: 12.70mm;
    top: 18.56mm;
    width: 18.99mm;
    height: 7.25mm;
    object-fit: contain;
}

.cdq .company-name {
    left: 34.28mm;
    top: 13.62mm;
    width: 95mm;
    overflow: hidden;
    font-size: 7mm;
    font-weight: 700;
    line-height: 7.40mm;
}

.cdq .company-address {
    left: 34.28mm;
    top: 22.82mm;
    width: 156mm;
    overflow: hidden;
    font-size: 4.60mm;
    line-height: 5.20mm;
}

.cdq .company-contact {
    left: 34.28mm;
    top: 29.02mm;
    font-size: 4.60mm;
    line-height: 5.20mm;
}

.cdq .company-tax-label,
.cdq .company-tax-value,
.cdq .company-branch {
    top: 35.63mm;
    font-size: 3.85mm;
    line-height: 4.40mm;
}

.cdq .company-tax-label { left: 34.28mm; }
.cdq .company-tax-value { left: 73.27mm; }
.cdq .company-branch { left: 100.08mm; }

.cdq .document-title {
    left: 131.48mm;
    top: 37.84mm;
    width: 59mm;
    height: 8.20mm;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0 2mm;
    border-radius: var(--cd-pill-radius);
    background: var(--copy-color);
    font-size: 5.25mm;
    font-weight: 700;
}

.cdq .copy-title {
    left: 131.48mm;
    top: 47.05mm;
    width: 59mm;
    height: 5.50mm;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 4.10mm;
    font-weight: 700;
}


/* Two equal top boxes */

.cdq .top-boxes {
    position: absolute;
    left: var(--cd-page-x);
    top: var(--cd-top-top);
    width: var(--cd-page-w);
    height: var(--cd-top-h);
    display: flex;
    align-items: stretch;
    gap: var(--cd-top-gap);
}

.cdq .info-box {
    flex: 1 1 0;
    min-width: 0;
    height: 100%;
    padding: 2mm 3.20mm;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border: var(--cd-rule);
    border-radius: var(--cd-radius);
    background: #fff;
}

.cdq .field-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.cdq .field-table td {
    height: 6.65mm;
    padding: 0 !important;
    border: 0;
    vertical-align: middle;
}

.cdq .field-label {
    width: 36.50mm;
    padding-right: 1.50mm !important;
    overflow: hidden;
    font-size: 3.55mm;
    font-weight: 700;
    line-height: 4mm;
    white-space: normal;
}

.cdq .field-value {
    overflow: hidden;
    font-size: 4.05mm;
    line-height: 4.35mm;
    white-space: normal;
    overflow-wrap: anywhere;
}

.cdq .field-value.is-strong {
    font-size: 4.40mm;
    font-weight: 700;
}

.cdq .customer-body {
    flex: 1 1 auto;
    min-height: 0;
    padding-top: .70mm;
    overflow: hidden;
}

.cdq .customer-top {
    display: flex;
    align-items: baseline;
    gap: 2mm;
}

.cdq .customer-name {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    font-size: 4.22mm;
    font-weight: 700;
    line-height: 4.70mm;
    white-space: nowrap;
    text-overflow: ellipsis;
}

.cdq .customer-code {
    flex: 0 0 auto;
    font-size: 3.70mm;
    line-height: 4.20mm;
    white-space: nowrap;
}

.cdq .customer-address {
    max-height: 22mm;
    margin-top: .80mm;
    overflow: hidden;
    font-size: 4mm;
    line-height: 4.35mm;
}

.cdq .customer-address p,
.cdq .field-value p {
    margin: 0 !important;
    padding: 0 !important;
    font: inherit !important;
    line-height: inherit !important;
}

.cdq .sales-contact-row {
    flex: 0 0 6.30mm;
    display: flex;
    align-items: center;
    border-top: .159mm solid #ccc;
}

.cdq .sales-contact-label {
    flex: 0 0 31mm;
    padding-right: 1.50mm;
    font-size: 3.55mm;
    font-weight: 700;
    white-space: nowrap;
}

.cdq .sales-contact-value {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    font-size: 3.90mm;
    white-space: nowrap;
    text-overflow: ellipsis;
}

.cdq .contact-dot {
    margin: 0 1mm;
}


/* Intro */

.cdq .quotation-intro {
    position: absolute;
    left: calc(var(--cd-page-x) + 1.20mm);
    top: var(--cd-intro-top);
    width: calc(var(--cd-page-w) - 2.40mm);
    height: var(--cd-intro-h);
    display: flex;
    align-items: center;
    overflow: hidden;
    font-size: 4.10mm;
    font-weight: 700;
    line-height: 5mm;
}


/* Item grid */

.cdq .quotation-grid {
    position: absolute;
    left: var(--cd-page-x);
    top: var(--cd-grid-top);
    width: var(--cd-page-w);
    height: var(--cd-grid-h);
    overflow: hidden;
    border: var(--cd-rule);
    border-radius: 2.18mm 2.18mm 0 0;
}

.cdq .grid-vline {
    position: absolute;
    top: 0;
    height: calc(var(--cd-head-h) + var(--cd-body-h));
    width: 0;
    border-left: var(--cd-rule);
    z-index: 3;
    pointer-events: none;
}

.cdq .line-no { left: var(--cd-x-desc); }
.cdq .line-description { left: var(--cd-x-qty); }
.cdq .line-quantity { left: var(--cd-x-rate); }
.cdq .line-rate { left: var(--cd-x-amount); }

.cdq .product-head {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: var(--cd-head-h);
    display: flex;
    background: var(--copy-color);
    border-bottom: var(--cd-rule);
}

.cdq .head-cell {
    height: var(--cd-head-h);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    padding: .35mm .55mm;
    font-size: 4.05mm;
    font-weight: 700;
    line-height: 4mm;
    text-align: center;
}

.cdq .product-head .col-no { flex: 0 0 var(--cd-col-no); }
.cdq .product-head .col-description { flex: 0 0 var(--cd-col-desc); }
.cdq .product-head .col-quantity { flex: 0 0 var(--cd-col-qty); }
.cdq .product-head .col-rate { flex: 0 0 var(--cd-col-rate); }
.cdq .product-head .col-amount { flex: 0 0 var(--cd-col-amount); }

.cdq .product-body {
    position: absolute;
    left: 0;
    top: var(--cd-head-h);
    width: 100%;
    height: var(--cd-body-h);
    overflow: hidden;
    border-bottom: var(--cd-rule);
}

.cdq .item-lines {
    position: relative;
    z-index: 2;
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.cdq .item-lines col.col-no { width: var(--cd-col-no); }
.cdq .item-lines col.col-description { width: var(--cd-col-desc); }
.cdq .item-lines col.col-quantity { width: var(--cd-col-qty); }
.cdq .item-lines col.col-rate { width: var(--cd-col-rate); }
.cdq .item-lines col.col-amount { width: var(--cd-col-amount); }

.cdq .item-lines td {
    padding-top: var(--cd-row-pad-top) !important;
    padding-right: 1.15mm !important;
    padding-bottom: var(--cd-row-pad-bottom) !important;
    padding-left: 1.15mm !important;
    overflow: hidden;
    border: 0;
    font-size: 4.10mm;
    line-height: var(--cd-row-line-h);
    vertical-align: top;
}

.cdq .cell-no {
    text-align: center;
}

.cdq .cell-description {
    padding-left: 1.35mm !important;
    padding-right: 1mm !important;
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.cdq .cell-quantity {
    text-align: center;
    white-space: nowrap;
}

.cdq .cell-money {
    padding-right: 1.25mm !important;
    text-align: right;
    white-space: nowrap;
}


/* Summary */

.cdq .summary-area {
    position: absolute;
    left: 0;
    top: calc(var(--cd-head-h) + var(--cd-body-h));
    width: 100%;
    height: var(--cd-summary-h);
    display: flex;
    border-bottom: var(--cd-rule);
}

.cdq .remarks-panel {
    flex: 0 0 100.90mm;
    min-width: 0;
    height: 100%;
    padding: 2mm 4.75mm 7mm;
    overflow: hidden;
    border-right: var(--cd-rule);
}

.cdq .remarks-title {
    font-size: 4.22mm;
    font-weight: 700;
    line-height: 5mm;
}

.cdq .summary-label-th {
    display: block;
    font-size: 3.85mm;
    font-weight: 700;
    line-height: 3.35mm;
}

.cdq .summary-label-en {
    display: block;
    color: var(--cd-muted);
    font-size: 2.55mm;
    font-weight: 400;
    line-height: 2.35mm;
}

.cdq .remarks-body {
    margin-top: 1.10mm;
    max-height: 17mm;
    overflow: hidden;
    font-size: 4.05mm;
    line-height: 4.25mm;
}

.cdq .remarks-body p,
.cdq .remarks-body div {
    margin: 0;
    font-size: inherit;
    line-height: inherit;
}

.cdq .remarks-sales-contact {
    margin-top: 1mm;
    font-size: 3.85mm;
    line-height: 4.10mm;
}

.cdq .totals-panel {
    flex: 1 1 auto;
    min-width: 0;
    height: 100%;
    display: flex;
    flex-direction: column;
}

.cdq .total-line {
    flex: 0 0 8.25mm;
    display: flex;
}

.cdq .total-line-label {
    flex: 0 0 48.34mm;
    padding: .38mm 1.20mm 0;
    overflow: hidden;
    border-right: var(--cd-rule);
}

.cdq .total-line-value {
    flex: 1 1 auto;
    padding: .58mm 1.05mm 0;
    overflow: hidden;
    font-size: 4mm;
    line-height: 5.20mm;
    text-align: right;
    white-space: nowrap;
}

.cdq .total-line-grand {
    flex-basis: 9.33mm;
    background: var(--copy-color);
}

.cdq .total-line-grand .total-line-label,
.cdq .total-line-grand .total-line-value {
    padding-top: 1.30mm;
}

.cdq .total-line-grand .total-line-value {
    font-size: 5.821mm;
    font-weight: 700;
    line-height: 6.40mm;
}

.cdq .totals-panel .words-row {
    flex: 1 1 auto;
    min-height: 0;
    padding: 1.20mm 1.50mm .80mm;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    overflow: hidden;
    border-top: var(--cd-rule);
    background: #f1f1f1;
    font-size: 3.55mm;
    font-weight: 700;
    line-height: 4.10mm;
    text-align: right;
    white-space: normal;
    overflow-wrap: anywhere;
}


/* Footer */

.cdq .quotation-footer {
    position: absolute;
    left: var(--cd-page-x);
    top: var(--cd-footer-top);
    width: var(--cd-page-w);
    height: var(--cd-footer-h);
    display: flex;
    overflow: hidden;
    border: var(--cd-rule);
    border-top: 0;
    border-radius: 0 0 2.18mm 2.18mm;
}

.cdq .bank-panel {
    flex: 0 0 100.90mm;
    padding: 2.50mm 4mm;
    border-right: var(--cd-rule);
}

.cdq .footer-title {
    margin-bottom: 1.50mm;
    font-size: 4.10mm;
    font-weight: 700;
    line-height: 4.60mm;
}

.cdq .bank-grid {
    display: grid;
    grid-template-columns: 28mm minmax(0, 1fr);
    column-gap: 2mm;
    row-gap: 1mm;
    align-items: baseline;
}

.cdq .bank-label {
    font-size: 3.85mm;
    font-weight: 700;
    line-height: 4.30mm;
    white-space: nowrap;
}

.cdq .bank-value {
    min-width: 0;
    overflow: hidden;
    font-size: 3.85mm;
    line-height: 4.30mm;
    white-space: nowrap;
    text-overflow: ellipsis;
}

.cdq .signature-panel {
    flex: 1 1 auto;
    padding: 2.30mm 4mm;
    display: flex;
    flex-direction: column;
    text-align: center;
}

.cdq .respect-text {
    flex: 0 0 5mm;
    font-size: 4mm;
    line-height: 4.50mm;
}

.cdq .signature-line {
    flex: 0 0 12mm;
    margin: 0 12mm;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    border-bottom: .159mm solid #565656;
}

.cdq .action-signature-image {
    width: 36mm;
    max-width: 100%;
    height: 10.50mm;
    object-fit: contain;
}

.cdq .signature-name {
    flex: 0 0 7mm;
    padding-top: 1mm;
    overflow: hidden;
    font-size: 3.85mm;
    line-height: 4.20mm;
    white-space: nowrap;
    text-overflow: ellipsis;
}

.cdq .signature-role {
    margin-left: .70mm;
}

.cdq .signature-date-row {
    margin-top: auto;
    display: flex;
    align-items: baseline;
    justify-content: center;
    gap: 1mm;
    font-size: 3.40mm;
    line-height: 4mm;
}

.cdq .signature-date {
    min-width: 22mm;
    border-bottom: .159mm solid #565656;
}


/* Bilingual compacting */

.cdq.cdq-bilingual .company-name {
    font-size: 5.25mm;
}

.cdq.cdq-bilingual .company-address,
.cdq.cdq-bilingual .company-contact,
.cdq.cdq-bilingual .company-tax-label,
.cdq.cdq-bilingual .company-tax-value,
.cdq.cdq-bilingual .company-branch {
    font-size: 3.70mm;
}

.cdq.cdq-bilingual .field-label,
.cdq.cdq-bilingual .sales-contact-label,
.cdq.cdq-bilingual .head-cell {
    font-size: 3.20mm;
}

.cdq.cdq-bilingual .field-value,
.cdq.cdq-bilingual .customer-name,
.cdq.cdq-bilingual .customer-address,
.cdq.cdq-bilingual .sales-contact-value,
.cdq.cdq-bilingual .item-lines td {
    font-size: 3.60mm;
}

.cdq.cdq-bilingual .quotation-intro,
.cdq.cdq-bilingual .footer-title,
.cdq.cdq-bilingual .bank-label,
.cdq.cdq-bilingual .bank-value,
.cdq.cdq-bilingual .respect-text {
    font-size: 3.40mm;
}

@media print {
    .cdq .top-boxes,
    .cdq .quotation-grid,
    .cdq .quotation-footer {
        break-inside: avoid;
        page-break-inside: avoid;
    }
}


/* Print rich text must expand naturally; never create an inner scrolling box. */
.cdq .remarks-body,
.cdq .remarks-body *,
.cdq .remarks-body .ql-container,
.cdq .remarks-body .ql-editor,
.cdq .remarks-body .read-mode,
.cdq .customer-address,
.cdq .customer-address *,
.cdq .field-value,
.cdq .field-value * {
    scrollbar-width: none !important;
}

.cdq .remarks-body .ql-container,
.cdq .remarks-body .ql-editor,
.cdq .remarks-body .read-mode {
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
    overflow: visible !important;
    overflow-x: visible !important;
    overflow-y: visible !important;
}

.cdq .remarks-body::-webkit-scrollbar,
.cdq .remarks-body *::-webkit-scrollbar,
.cdq .customer-address::-webkit-scrollbar,
.cdq .customer-address *::-webkit-scrollbar,
.cdq .field-value::-webkit-scrollbar,
.cdq .field-value *::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;
    display: none !important;
}


/* Payment information: one vertical label/value pair per row. */
.cdq .bank-panel {
    overflow: hidden;
}

.cdq .bank-label,
.cdq .bank-value {
    min-width: 0;
}

.cdq .bank-value {
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
    overflow-wrap: anywhere;
}

html:
{#
ERPNext Custom Print Format: Quotation
Connect Diagnostics — original visual language, Sales Invoice-style structure.

IMPORTANT pagination contract:
CSS product body = 91.50mm
Backend quotation usable height = 90.50mm
The 1.00mm difference is a PDF/rendering safety margin.
#}

{% macro corporate_header(
company_name,
company_address,
company_contact,
tax_label,
tax_id,
branch,
document_title,
copy_title,
logo_src="/assets/connect_diagnostics_core/images/cd_logo_v2.jpg",
logo_alt="Connect Diagnostics"
) -%}
<header class="document-header cd-corporate-header">
    <img class="company-logo" src="{{ logo_src }}" alt="{{ logo_alt }}">
    <div class="company-name">{{ company_name }}</div>
    <div class="company-address">{{ company_address }}</div>
    <div class="company-contact">{{ company_contact }}</div>
    <div class="company-tax-label">{{ tax_label }}</div>
    <div class="company-tax-value">{{ tax_id }}</div>
    <div class="company-branch">{{ branch }}</div>
    <div class="document-title">{{ document_title }}</div>
    <div class="copy-title">{{ copy_title }}</div>
</header>
{%- endmacro %}

{% macro item_table(columns=(), classes="") -%}
<table class="cd-table{% if classes %} {{ classes }}{% endif %}">
    {% if columns %}
    <colgroup>
        {% for class_name in columns %}
        <col{% if class_name %} class="{{ class_name }}"{% endif %}>
        {% endfor %}
    </colgroup>
    {% endif %}
    {{ caller() }}
</table>
{%- endmacro %}

{% macro field_row(label_text, value, strong=False, classes="") -%}
<tr{% if classes %} class="{{ classes }}"{% endif %}>
    <td class="field-label">{{ label_text }}</td>
    <td class="field-value{% if strong %} is-strong{% endif %}">{{ value }}</td>
</tr>
{%- endmacro %}

{% macro summary_label(thai, english) -%}
<span class="summary-label-th">{{ thai }}</span>
<span class="summary-label-en">{{ english }}</span>
{%- endmacro %}

{% set print_context = get_quotation_print_context(doc) %}
{% set print_actions = print_context.print_actions or {} %}
{% set signatory_action = print_actions.get("signatory", {}) %}

{% macro label(thai, english) -%}
{%- if print_context.show_thai %}{{ thai }}{% endif -%}
{%- if print_context.show_thai and print_context.show_english %} / {% endif -%}
{%- if print_context.show_english %}{{ english }}{% endif -%}
{%- endmacro %}

{% set customer_address_display = (doc.address_display or "") | safe %}
{% set delivery_text = print_context.delivery_terms or "" %}
{% set validity_text = print_context.validity_text or "" %}
{% set sales_contact = print_context.sales_contact or {} %}
{% set sales_contact_name = sales_contact.name or "" %}
{% set sales_contact_phone = sales_contact.phone or "" %}
{% set attention_text = doc.contact_display or label("ผู้จัดการ", "Manager") %}
{% set customer_code = doc.customer or doc.party_name or "" %}
{% set customer_name = print_context.customer_name or doc.customer_name or customer_code %}

{% set item_pages = get_print_item_pages(doc, "quotation") %}
{% set item_page_count = item_pages | length %}

{% for copy in print_context.copies %}
{% set copy_loop = loop %}

{% for page_items in item_pages %}
{% set page_loop = loop %}
{% set current_print_page = page_loop.index %}
{% set page_metrics = get_print_page_metrics(page_items, 90.5) %}

<article
    class="cdq cd-a4-page{% if print_context.show_thai and print_context.show_english %} cdq-bilingual{% endif %}{% if copy_loop.last and page_loop.last %} last-page{% endif %}"
    data-item-used-mm="{{ page_metrics.used_height_mm }}"
    data-item-remaining-mm="{{ page_metrics.remaining_height_mm }}">

{{ corporate_header(
    company_name=label("บริษัท คอนเนค ไดแอกโนสติกส์ จำกัด", "Connect Diagnostics Co., Ltd."),
    company_address=label(
        "1/57-58 เวนิส ดี ไอริส ซอยวัชรพล 2/7 แขวงท่าแร้ง เขตบางเขน กรุงเทพฯ 10220",
        "1/57-58 Venice Di Iris, Soi Watcharaphon 2/7, Tha Raeng, Bang Khen, Bangkok 10220"
    ),
    company_contact=label("โทร", "Tel.") ~ " 02-347-0109&nbsp;&nbsp;&nbsp; www.connectdiagnostics.com",
    tax_label=label("เลขประจำตัวผู้เสียภาษี", "Tax ID"),
    tax_id="0105551058581",
    branch=label("สำนักงานใหญ่", "Head Office"),
    document_title=label("ใบเสนอราคา", "Quotation"),
    copy_title=copy.label
) }}

<section class="top-boxes">

    <section class="info-box customer-box">
        <table class="field-table">
            <tbody>
                {{ field_row(label("เรียน", "Attention"), attention_text | safe) }}
            </tbody>
        </table>

        <div class="customer-body">
            <div class="customer-top">
                <div class="customer-name">{{ customer_name }}</div>
                <div class="customer-code">{{ customer_code }}</div>
            </div>
            <div class="customer-address">{{ customer_address_display }}</div>
        </div>

        <div class="sales-contact-row">
            <div class="sales-contact-label">{{ label("ผู้แทนฝ่ายขาย", "Sales Contact") }}</div>
            <div class="sales-contact-value">
                {% if sales_contact_name %}<span>{{ sales_contact_name }}</span>{% endif %}
                {% if sales_contact_name and sales_contact_phone %}<span class="contact-dot">•</span>{% endif %}
                {% if sales_contact_phone %}<span>{{ sales_contact_phone }}</span>{% endif %}
            </div>
        </div>
    </section>

    <section class="info-box quotation-box">
        <table class="field-table quotation-fields">
            <tbody>
                {{ field_row(label("เลขที่ใบเสนอราคา", "Quotation No."), doc.name, strong=True) }}
                {{ field_row(label("วันที่", "Date"), format_date(doc.transaction_date) if print_context.show_date else "") }}
                {{ field_row(label("หน้า", "Page"), current_print_page ~ " / " ~ item_page_count) }}
                {{ field_row(label("กำหนดยืนราคา", "Validity"), validity_text) }}
                {{ field_row(label("กำหนดส่งมอบสินค้า", "Delivery Terms"), delivery_text) }}
                {{ field_row(label("เงื่อนไขการชำระเงิน", "Payment Terms"), doc.payment_terms_template or "") }}
            </tbody>
        </table>
    </section>

</section>

<div class="quotation-intro">
    {{ label(
        "บริษัท คอนเนค ไดแอกโนสติกส์ จำกัด มีความยินดีขอเสนอราคา โดยมีรายละเอียดดังต่อไปนี้",
        "Connect Diagnostics Co., Ltd. is pleased to submit this quotation as detailed below."
    ) }}
</div>

<section class="quotation-grid">

    <span class="grid-vline line-no"></span>
    <span class="grid-vline line-description"></span>
    <span class="grid-vline line-quantity"></span>
    <span class="grid-vline line-rate"></span>

    <div class="product-head">
        <div class="head-cell col-no">{{ label("ลำดับ", "No.") }}</div>
        <div class="head-cell col-description">{{ label("รายการ", "Description") }}</div>
        <div class="head-cell col-quantity">{{ label("จำนวน", "Quantity") }}</div>
        <div class="head-cell col-rate">{{ label("ราคาต่อหน่วย", "Unit Price") }}</div>
        <div class="head-cell col-amount">{{ label("ราคารวม", "Amount") }}</div>
    </div>

    <div class="product-body">
        {% call item_table(
            ["col-no", "col-description", "col-quantity", "col-rate", "col-amount"],
            classes="item-lines"
        ) %}
        <tbody>
            {% for entry in page_items %}
            {% set row = entry.row %}
            <tr class="item-row" style="height: {{ entry.height_mm }}mm;">
                <td class="cell-no">{{ row.idx or loop.index }}</td>
                <td class="cell-description">
                    {{ (row.description | striptags | trim) if row.description else row.item_name }}
                </td>
                <td class="cell-quantity">
                    {{ frappe.format(row.qty, {"fieldtype": "Float"}) }}
                    {% if row.uom %}&nbsp;&nbsp;{{ row.uom }}{% endif %}
                </td>
                <td class="cell-money">{{ format_money(row.rate) }}</td>
                <td class="cell-money">{{ format_money(row.amount) }}</td>
            </tr>
            {% endfor %}
        </tbody>
        {% endcall %}
    </div>

    <div class="summary-area">
        <section class="remarks-panel">
            <div class="remarks-title">{{ summary_label("หมายเหตุ", "Remarks") }}</div>
            <div class="remarks-body">{{ (doc.terms or "") | safe }}</div>

            {% if sales_contact_name or sales_contact_phone %}
            <div class="remarks-sales-contact">
                {{ label(
                    "สอบถามข้อมูลเพิ่มเติม สามารถติดต่อ ผู้แทนฝ่ายขาย",
                    "For more information, please contact the sales representative."
                ) }}
                <br>
                {{ sales_contact_name }}
                {% if sales_contact_name and sales_contact_phone %}&nbsp;&nbsp;{% endif %}
                {{ sales_contact_phone }}
            </div>
            {% endif %}
        </section>

        <section class="totals-panel">
            <div class="total-line">
                <div class="total-line-label">
                    {{ summary_label("ราคาก่อนภาษีมูลค่าเพิ่ม", "Subtotal before VAT") }}
                </div>
                <div class="total-line-value">{{ format_money(doc.net_total) }}</div>
            </div>

            <div class="total-line">
                <div class="total-line-label">
                    {{ summary_label("ภาษีมูลค่าเพิ่ม 7 %", "VAT Amount") }}
                </div>
                <div class="total-line-value">{{ format_money(doc.total_taxes_and_charges) }}</div>
            </div>

            <div class="total-line total-line-grand">
                <div class="total-line-label">
                    {{ summary_label("รวมเป็นเงินทั้งสิ้น", "Grand Total") }}
                </div>
                <div class="total-line-value">{{ format_money(doc.grand_total) }}</div>
            </div>

            <div class="words-row">
                ({{ label(
                    number_to_thai_currency(doc.grand_total or 0, doc.currency),
                    doc.in_words or ""
                ) }}).
            </div>
        </section>
    </div>

</section>

<footer class="quotation-footer">

    <section class="bank-panel">
        <div class="footer-title">{{ label("ข้อมูลการชำระเงิน", "Payment Information") }}</div>

        <div class="bank-grid">
            <div class="bank-label">{{ label("เลขที่บัญชี", "Account No.") }}</div>
            <div class="bank-value">796-2-03330-4</div>

            <div class="bank-label">{{ label("ธนาคาร", "Bank") }}</div>
            <div class="bank-value">{{ label("กสิกรไทย", "Kasikornbank") }}</div>

            <div class="bank-label">{{ label("สาขา", "Branch") }}</div>
            <div class="bank-value">{{ label("ซอยวัชรพล", "Soi Watcharaphon") }}</div>

            <div class="bank-label">{{ label("ชื่อบัญชี", "Account Name") }}</div>
            <div class="bank-value">
                {{ label("บจก. คอนเนค ไดแอกโนสติกส์", "Connect Diagnostics Co., Ltd.") }}
            </div>
        </div>
    </section>

    <section class="signature-panel">
        <div class="respect-text">{{ label("ขอแสดงความนับถือ", "Yours sincerely") }}</div>

        <div class="signature-line">
            {% if print_context.signatory.signature %}
            <img class="action-signature-image"
                 src="{{ print_context.signatory.signature | e }}"
                 alt="">
            {% endif %}
        </div>

        <div class="signature-name">
            {% if print_context.signatory.name %}{{ print_context.signatory.name }}{% endif %}
            {% if print_context.signatory.caption %}
            <span class="signature-role">({{ print_context.signatory.caption }})</span>
            {% endif %}
        </div>

        <div class="signature-date-row">
            <span class="signature-date">
                {% if signatory_action.get("acted_at") %}
                {{ format_date(signatory_action.get("acted_at")) }}
                {% endif %}
            </span>
            <span>{{ label("วันที่", "Date") }}</span>
        </div>
    </section>

</footer>

</article>

{% endfor %}
{% endfor %}
